using System;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "DicesmithHelmetOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/DicesmithHelmet Omen Data")]
public class DicesmithHelmetOmenData : OmenData
{
	[Header("Azimuth Ring")]
	[SerializeField]
	private PlayerDiceInventoryData allDicePool;

	[SerializeField]
	private int diceAmountToStartIncreasingPurify;

	[SerializeField]
	private IncreasePurifyReceivedByEnemiesOmenData increasePurifyReceivedByEnemiesOmenData;

	[SerializeField]
	private int afterDiceAmountToIncreasePurifyAmount;

	private Func<int, int> omenAction;

	private OmenInstance omenInstance;

	private int additionalPurify;

	public override void Initialize(OmenInstance omenInstance)
	{
		this.omenInstance = omenInstance;
		UpdateAdditionalPurify();
		omenAction = (int purifyAmount) => purifyAmount + additionalPurify;
		ReferenceSingleton<PurifyOmensHandler>.Instance.OnEnemyReceivePurifyModifierOmenActions.Add(omenAction);
		ReferenceSingleton<PurifyOmensHandler>.Instance.DicesmithHelmetAction = delegate
		{
			UpdateAdditionalPurify();
		};
	}

	private void UpdateAdditionalPurify()
	{
		if (allDicePool.GetDicesAmount() >= diceAmountToStartIncreasingPurify)
		{
			additionalPurify = ActionValue;
			additionalPurify += Mathf.CeilToInt((float)(allDicePool.GetDicesAmount() + 1 - (diceAmountToStartIncreasingPurify + TriggerAmount)) / (float)TriggerAmount) * afterDiceAmountToIncreasePurifyAmount;
			counter = additionalPurify;
		}
		else
		{
			additionalPurify = 0;
			counter = 0;
		}
		counter = additionalPurify;
		if (omenInstance != null)
		{
			omenInstance.UpdateOmenCounter();
		}
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<PurifyOmensHandler>.Instance.OnEnemyReceivePurifyModifierOmenActions.Remove(omenAction);
		ReferenceSingleton<PurifyOmensHandler>.Instance.DicesmithHelmetAction = null;
	}

	public override string OmenConvertedDescription()
	{
		string text = increasePurifyReceivedByEnemiesOmenData.GetIncreasePurifyReceivedByEnemiesLocalizedString(ActionValue).RemoveLast().LowercaseFirst();
		string text2 = increasePurifyReceivedByEnemiesOmenData.GetIncreasePurifyReceivedByEnemiesLocalizedString(afterDiceAmountToIncreasePurifyAmount).RemoveLast().LowercaseFirst();
		string text3 = Smart.Format(GetOmenRawLocalizedDescription(), diceAmountToStartIncreasingPurify, text, TriggerAmount, text2);
		if (ReferenceSingleton<BattleHandler>.Instance != null)
		{
			string text4 = string.Format("\n" + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedPreviewDescription(), increasePurifyReceivedByEnemiesOmenData.GetIncreasePurifyReceivedByEnemiesLocalizedString(additionalPurify).RemoveLast());
			text3 += text4;
		}
		return text3;
	}

	public override void InitializeActionDescriptionPanel()
	{
		UpdateAdditionalPurify();
	}
}
